import{_t as e,it as t,n,rt as r}from"./chunks/framework.C1oW5ckO.js";var i=JSON.parse(`{"title":"Plugin build tool","description":"","frontmatter":{"editLink":"https://github.com/filiphsps/pumpkin-plugins/edit/master/tools/build/docs/index.md"},"headers":[],"relativePath":"tools/build/docs/index.md","filePath":"tools/build/docs/index.md","lastUpdated":1792005884000}`),a={name:`tools/build/docs/index.md`};function o(n,i,a,o,s,c){return e(),r(`div`,null,[...i[0]||=[t(`<h1 id="plugin-build-tool" tabindex="-1">Plugin build tool <a class="header-anchor" href="#plugin-build-tool" aria-label="Permalink to “Plugin build tool”">​</a></h1><p><code>@pumpkin-plugins/build</code> turns a plugin&#39;s TypeScript entry point into a Pumpkin WebAssembly component. It bundles the plugin, adds the WASI imports declared by the package, componentizes the module with the repository&#39;s pinned toolchain, and can generate guest declarations for typechecking.</p><h2 id="build-a-plugin" tabindex="-1">Build a plugin <a class="header-anchor" href="#build-a-plugin" aria-label="Permalink to “Build a plugin”">​</a></h2><p>Run <code>pnpm build</code> from a plugin package. The build configuration is the <code>pumpkinPlugin</code> object in that package&#39;s <code>package.json</code>; it identifies the entry point, output file, and requested WASI capabilities. The result is the configured <code>.wasm</code> file under the package&#39;s build directory. The optional <code>engine</code> setting defaults to <code>static-hermes</code>; set it to <code>quickjs</code> to build a QuickJS plugin. Both engines are supported, and current plugin packages use the Static Hermes default. Static Hermes is the WASI 2 backend described in the <a href="./../../static-hermes-runtime/README">runtime guide</a>. It uses the lean runtime archive and Hades garbage collector by default. Set <code>staticHermesRuntime</code> to <code>&quot;full&quot;</code> to retain runtime source compilation, or set <code>STATIC_HERMES_ENABLE_LEAN_ARCHIVE=0</code> to disable the lean archive for builds. Set <code>staticHermesGc</code> to <code>&quot;malloc&quot;</code> to select malloc-managed GC.</p><p>The executable is compiled from TypeScript to <code>dist/cli.js</code>. Repository-wide build and typecheck commands compile it before consumers run. For a direct workspace package command after a fresh checkout, first run <code>pnpm --filter @pumpkin-plugins/static-hermes-runtime build</code> and <code>pnpm --filter @pumpkin-plugins/build build</code> from the repository root. Use <code>pumpkin-plugins-build --help</code> to list options and <code>--version</code> to show the installed tool version.</p><p>Run the build command with <code>--types-only</code> to generate guest types without producing the component. Those declarations are consumed by TypeScript and the editor. They are build output, so edit the plugin source and package configuration rather than generated files.</p><p>Pass <code>--parse-ts</code> to use Hermes&#39;s partial, unstable TypeScript parser when compiling a Static Hermes component bundle. The option is off by default and is unavailable with QuickJS.</p><p>The build tool owns console output for both engines. It reports the entry point, selected runtime, componentization stage and final artifact size with a shared <code>[build]</code> prefix. Routine output from the QuickJS and Static Hermes toolchains is suppressed; failures include captured stderr diagnostics in the same format.</p><p>On an interactive terminal, the executable checks npm in the background and may print a notice when a newer builder release is available. The lookup uses a one-day cache; registry errors do not affect the build result. It is skipped for help and version output, CI, development mode (<code>PUMPKIN_DEV_MODE=1</code>), and non-interactive output. Pass <code>--no-update-notifier</code> or set <code>PUMPKIN_PLUGINS_NO_UPDATE_NOTIFIER=1</code> to opt out. When a notice appears, preview the release migration from the plugin directory with <code>pnpm dlx @pumpkin-plugins/codemod update-build .</code>.</p><h2 id="build-constraints" tabindex="-1">Build constraints <a class="header-anchor" href="#build-constraints" aria-label="Permalink to “Build constraints”">​</a></h2><p>Static Hermes uses the pinned Pumpkin API WIT and WASI 2. Keep the workspace&#39;s Pumpkin API version aligned with the test harness server version. Requested WASI capabilities and Pumpkin permissions must match the APIs the plugin uses.</p><p>Identical source builds are not byte-for-byte reproducible. Signing or publishing workflows must use the exact artifact from the build job instead of rebuilding it later.</p>`,12)]])}var s=n(a,[[`render`,o]]);export{i as __pageData,s as default};